"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ArrowCounterClockwiseIcon as PhReset, ClockCounterClockwiseIcon as PhHistory } from "@phosphor-icons/react";

interface Snapshot {
  id: number;
  headline: string;
  bio: string;
}

const DEFAULT_HEADLINE = "Product designer, ex-Figma";
const DEFAULT_BIO = "I like clean interfaces and stubborn bugs.";
const COMMIT_DELAY = 900;
const FLASH_MS = 550;

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}
function HistoryIcon() {
  return <PhHistory size={13} aria-hidden />;
}

function PendingRing({ progress }: { progress: number }) {
  const size = 10;
  const strokeWidth = 2;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="-rotate-90" aria-hidden>
      <circle cx={size / 2} cy={size / 2} r={radius} fill="none" stroke="currentColor" strokeOpacity={0.25} strokeWidth={strokeWidth} className="text-slate-400 dark:text-slate-600" />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={circumference * (1 - progress)}
        className="text-emerald-500"
      />
    </svg>
  );
}

function initialHistory(): Snapshot[] {
  return [{ id: 0, headline: DEFAULT_HEADLINE, bio: DEFAULT_BIO }];
}

interface HistoryRailProps {
  className?: string;
}

export function HistoryRail({ className }: HistoryRailProps) {
  const [history, setHistory] = useState<Snapshot[]>(initialHistory);
  const [pointer, setPointer] = useState(0);
  const [headline, setHeadline] = useState(DEFAULT_HEADLINE);
  const [bio, setBio] = useState(DEFAULT_BIO);
  const [flash, setFlash] = useState(false);
  const [hoverId, setHoverId] = useState<number | null>(null);
  const [pendingProgress, setPendingProgress] = useState(0);
  const [celebrateId, setCelebrateId] = useState<number | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const flashTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const celebrateTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const committed = history[pointer];
  const isPending = !committed || committed.headline !== headline || committed.bio !== bio;

  const celebrate = (id: number) => {
    setCelebrateId(id);
    if (celebrateTimeoutRef.current) clearTimeout(celebrateTimeoutRef.current);
    celebrateTimeoutRef.current = setTimeout(() => setCelebrateId(null), 650);
  };

  const commitSnapshot = () => {
    const current = history[pointer];
    if (current && current.headline === headline && current.bio === bio) return;
    const truncated = history.slice(0, pointer + 1);
    const created = { id: Date.now(), headline, bio };
    const next = [...truncated, created];
    setHistory(next);
    setPointer(next.length - 1);
    celebrate(created.id);
  };

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(commitSnapshot, COMMIT_DELAY);
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [headline, bio]);

  useEffect(() => {
    if (!isPending) {
      setPendingProgress(0);
      return;
    }
    const start = performance.now();
    let raf: number;
    const tick = () => {
      const elapsed = performance.now() - start;
      setPendingProgress(Math.min(1, elapsed / COMMIT_DELAY));
      if (elapsed < COMMIT_DELAY) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [isPending, headline, bio]);

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current);
      if (celebrateTimeoutRef.current) clearTimeout(celebrateTimeoutRef.current);
    };
  }, []);

  const jumpTo = (index: number) => {
    if (index === pointer) return;
    if (debounceRef.current) clearTimeout(debounceRef.current);
    commitSnapshot();
    const snap = history[index];
    if (!snap) return;
    setPointer(index);
    setHeadline(snap.headline);
    setBio(snap.bio);
    setFlash(true);
    celebrate(snap.id);
    if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current);
    flashTimeoutRef.current = setTimeout(() => setFlash(false), FLASH_MS);
  };

  const reset = () => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (flashTimeoutRef.current) clearTimeout(flashTimeoutRef.current);
    if (celebrateTimeoutRef.current) clearTimeout(celebrateTimeoutRef.current);
    setHistory(initialHistory());
    setPointer(0);
    setHeadline(DEFAULT_HEADLINE);
    setBio(DEFAULT_BIO);
    setFlash(false);
    setCelebrateId(null);
  };

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
            <HistoryIcon />
            <span className="text-xs font-semibold uppercase tracking-wide">Edit history</span>
          </div>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset history"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>
        <p className="mt-1 text-xs text-slate-400 dark:text-slate-500">
          Checkpoint {pointer + 1} of {history.length}
          {isPending ? ", recording your latest edit" : ""}.
        </p>

        <div className="relative mt-3 flex h-8 items-center">
          <div className="absolute inset-x-0 top-1/2 h-px -translate-y-1/2 bg-slate-200 dark:bg-white/10" />
          <div className="relative flex items-center gap-2.5">
            <AnimatePresence initial={false}>
              {history.map((snap, i) => {
                const isCurrent = i === pointer;
                const isFuture = i > pointer;
                return (
                  <motion.button
                    key={snap.id}
                    type="button"
                    onClick={() => jumpTo(i)}
                    onMouseEnter={() => setHoverId(snap.id)}
                    onMouseLeave={() => setHoverId((h) => (h === snap.id ? null : h))}
                    onFocus={() => setHoverId(snap.id)}
                    onBlur={() => setHoverId((h) => (h === snap.id ? null : h))}
                    aria-label={`Checkpoint ${i + 1}${isCurrent ? ", current" : ""}`}
                    aria-current={isCurrent}
                    initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                    whileTap={shouldReduceMotion ? undefined : { scale: 0.8 }}
                    transition={{ type: "spring", stiffness: 500, damping: 26 }}
                    className="relative flex shrink-0 items-center justify-center focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600"
                    style={{ width: isCurrent ? 16 : 10, height: isCurrent ? 16 : 10 }}
                  >
                    {celebrateId === snap.id && !shouldReduceMotion && (
                      <motion.span
                        aria-hidden
                        className="absolute rounded-full border-2 border-emerald-400/60"
                        style={{ inset: -3 }}
                        initial={{ scale: 0.7, opacity: 0.9 }}
                        animate={{ scale: 1.9, opacity: 0 }}
                        transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                      />
                    )}
                    <span
                      className={`h-full w-full rounded-full border-2 transition-colors ${
                        isCurrent
                          ? "border-emerald-600 bg-emerald-600"
                          : isFuture
                            ? "border-dashed border-amber-400/70 bg-transparent"
                            : "border-slate-300 bg-slate-300 dark:border-slate-600 dark:bg-slate-600"
                      }`}
                    />
                    <AnimatePresence>
                      {hoverId === snap.id && !isCurrent && (
                        <motion.span
                          role="tooltip"
                          initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, scale: 0.9 }}
                          animate={{ opacity: 1, y: 0, scale: 1 }}
                          exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4, scale: 0.9 }}
                          transition={{ type: "spring", stiffness: 500, damping: 30 }}
                          className="pointer-events-none absolute -top-9 left-1/2 z-10 flex max-w-[160px] -translate-x-1/2 items-center gap-1 whitespace-nowrap rounded-md bg-slate-900 px-2 py-1 text-xs font-medium text-white dark:bg-slate-100 dark:text-slate-900"
                        >
                          {snap.headline || "Empty headline"}
                          <span aria-hidden className="absolute left-1/2 top-full -mt-1 h-2 w-2 -translate-x-1/2 rotate-45 bg-slate-900 dark:bg-slate-100" />
                        </motion.span>
                      )}
                    </AnimatePresence>
                  </motion.button>
                );
              })}
            </AnimatePresence>
            <AnimatePresence>
              {isPending && (
                <motion.span
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.4 }}
                  transition={{ type: "spring", stiffness: 500, damping: 26 }}
                  className="flex shrink-0 items-center gap-1.5"
                >
                  <PendingRing progress={pendingProgress} />
                  <span className="whitespace-nowrap text-[11px] text-emerald-600 dark:text-emerald-400">Recording&hellip;</span>
                </motion.span>
              )}
            </AnimatePresence>
          </div>
        </div>

        <div
          className={`mt-3 flex flex-col gap-3 rounded-xl transition-shadow duration-300 ${
            flash ? "shadow-[0_0_0_3px_rgba(5,150,105,0.35)]" : "shadow-[0_0_0_3px_rgba(5,150,105,0)]"
          }`}
        >
          <label className="flex flex-col gap-1">
            <span className="text-xs font-medium text-slate-500 dark:text-slate-400">Headline</span>
            <input
              type="text"
              value={headline}
              onChange={(e) => setHeadline(e.target.value)}
              className="rounded-lg border border-slate-200/70 bg-white/60 px-3 py-2 text-sm text-slate-800 focus:outline-none focus-visible:border-emerald-500 dark:border-white/10 dark:bg-white/5 dark:text-slate-100"
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className="text-xs font-medium text-slate-500 dark:text-slate-400">Bio</span>
            <textarea
              value={bio}
              onChange={(e) => setBio(e.target.value)}
              rows={2}
              className="resize-none rounded-lg border border-slate-200/70 bg-white/60 px-3 py-2 text-sm text-slate-800 focus:outline-none focus-visible:border-emerald-500 dark:border-white/10 dark:bg-white/5 dark:text-slate-100"
            />
          </label>
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Type in either field, pause, then jump between checkpoints. Nothing ever asks you to confirm losing anything.
      </p>
    </div>
  );
}
